-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Requiere 01_esquema.sql (la tabla enemies).
--
-- Enemigos de Honkai: Star Rail: los 375 del juego (version 4.5), divididos en
-- jefes (110) y esbirros (265, de los que 113 son elites).
--
-- Fuentes:
--   Datos del propio juego (TurnBasedGameData, de Dimbreath) -> nombre y
--     descripcion oficiales en espanol, rango, debilidades, resistencias,
--     faccion y habilidades.
--   Nanoka (static.nanoka.cc) -> imagen de cada enemigo.
--
-- Un mismo enemigo aparece en el juego con varias versiones (por dificultad o
-- por contenido) que a veces cambian de debilidades: van juntas en una fila, y
-- las combinaciones distintas quedan en la columna variants.
--
-- Inserta lo que falte y actualiza lo que ya exista, sin borrar nada.
--
-- Generado el 2026-09-15.

--
-- PARTE 1 de 3 (92 filas). El archivo entero no cabia en el SQL Editor:
-- ejecuta las 3 partes, en cualquier orden.

insert into public.enemies (
  id, game_id, name, name_en, category, rank, faction, description, image_url, weaknesses, resistances, variants, skills
)
values
  ('hsr-enemy-1004014', 'honkai-star-rail', 'Aniquiladora del Mistral Desolador', 'Annihilator of Desolation Mistral', 'jefe', 'jefe', null, 'La Aniquiladora del Mistral Desolador posee la autoridad divina heredada por generaciones de Guardianas Supremas, lo que le confiere el poder de comandar el hielo y la nieve para congelar a sus enemigos en combate.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_1004010.webp', '["Fuego","Rayo","Viento","Cuántico"]'::jsonb, '[{"elemento":"Físico","valor":40},{"elemento":"Hielo","valor":60},{"elemento":"Imaginario","valor":60}]'::jsonb, null, '[{"nombre":"Escalofrío perforahuesos","descripcion":"Inflige Daño de Hielo a un aliado.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Presagio de la Edad de Hielo","descripcion":"Invoca a Pica Glacial.","tipo":"Habilidad","elemento":null},{"nombre":"Castigo del invierno eterno","descripcion":"Inflige una gran cantidad de Daño de Hielo a todos los aliados.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Escarcha aprisionada","descripcion":"Inflige Daño de Hielo a un aliado y tiene una gran probabilidad de congelar a ese aliado.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Furia de los santos de la tundra","descripcion":"Entra en el estado de Recarga. En su siguiente acción, utiliza Castigo del invierno eterno contra todos los aliados.","tipo":"Habilidad","elemento":null},{"nombre":"Hielo reverberante","descripcion":"Inflige Daño de Hielo a un aliado congelado y a los aliados adyacentes y disipa el estado de Congelación del objetivo principal. Si alguno de los aliados adyacentes está congelado, vuelve a usar esta habilidad contra el objetivo principal.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Frío intensificado","descripcion":"Por cada aliado afectado por Congelación, aumenta su daño infligido y el de las criaturas invocadas.","tipo":"Talento","elemento":null},{"nombre":"Escudo del reino de las nieves","descripcion":"Gepard se une a la batalla.","tipo":"Talento","elemento":null},{"nombre":"Fuerza irresistible","descripcion":"El daño que recibe la Aniquiladora del Mistral Desolador se reduce en gran medida. Pero, tras romper su Debilidad, su acción se retrasa adicionalmente y el daño que recibe aumenta, mientras que todos los aliados recuperan pts. de habilidad básica y activan sus habilidades definitivas.","tipo":"Talento","elemento":null},{"nombre":"Mistral Desolador","descripcion":"La Aniquiladora del Mistral Desolador transfiere sus tipos de Debilidad a Pica Glacial. Cuando Pica Glacial es derrotada, la Aniquiladora del Mistral Desolador recibe Reducción de Firmeza adicional.","tipo":"Talento","elemento":null},{"nombre":"Sin escapatoria","descripcion":"Cuando la Aniquiladora del Mistral Desolador lanza Escalofrío perforahuesos o Escarcha aprisionada, efectúa un lanzamiento adicional a los objetivos fijados por Pica Glacial.","tipo":"Talento","elemento":null},{"nombre":"Resolución tenaz","descripcion":"Reduce el daño que reciben todos los enemigos, pero aumenta el daño recibido por cada tipo de Debilidad poseído.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-1005014', 'honkai-star-rail', 'Aniquiladora del Mistral Desolador: Madre de Falsedades', 'Annihilator of Desolation Mistral: Mother of Deception', 'jefe', 'jefe', null, 'Tras ser asimilada por la energía del Fragmentum que desbordaba del Estelaron, la Guardiana Suprema adquirió la habilidad de controlar la energía imaginaria y es la portavoz del nuevo mundo que prometió.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_1005010.webp', '["Fuego","Rayo","Viento","Cuántico"]'::jsonb, '[{"elemento":"Físico","valor":40},{"elemento":"Hielo","valor":60},{"elemento":"Imaginario","valor":60}]'::jsonb, null, '[{"nombre":"Frío rompehuesos","descripcion":"Inflige Daño de Hielo a un aliado.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Advertencia del heraldo","descripcion":"Fija como objetivo a un aliado y utiliza Torrente destrozaalmas contra ese objetivo en su siguiente acción.","tipo":"Habilidad","elemento":null},{"nombre":"Torrente destrozaalmas","descripcion":"Inflige una gran cantidad de Daño de Hielo a un aliado y tiene una gran probabilidad de congelar a ese aliado.","tipo":"Habilidad","elemento":"Hielo"},{"nombre":"Llamada del exterminador","descripcion":"Invoca a la Lanza del Frío Infinito.","tipo":"Habilidad","elemento":null},{"nombre":"Resolución del creador","descripcion":"Cambia a tipo Imaginario, aumenta su VEL y el daño que inflige.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Acorde del génesis","descripcion":"Inflige Daño Imaginario a un aliado y tiene una gran probabilidad de aprisionarlo.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Preludio de la creación","descripcion":"Entra en el estado de Recarga. En su siguiente acción, utiliza Último coro del génesis contra todos los aliados.","tipo":"Habilidad","elemento":null},{"nombre":"Último coro del génesis","descripcion":"Inflige una gran cantidad de Daño Imaginario a todos los aliados.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Catástrofe nevada","descripcion":"Por cada aliado afectado por Congelación o Prisión, aumenta su daño infligido y el de las criaturas invocadas.","tipo":"Talento","elemento":null},{"nombre":"Fuerza irresistible","descripcion":"El daño que recibe la Aniquiladora del Mistral Desolador: Madre de Falsedades se reduce en gran medida. Pero, tras romper su Debilidad, su acción se retrasa adicionalmente y el daño que recibe aumenta, mientras que todos los aliados recuperan pts. de habilidad básica y activan sus habilidades definitivas.","tipo":"Talento","elemento":null},{"nombre":"Mistral Desolador","descripcion":"La Aniquiladora del Mistral Desolador: Madre de Falsedades transfiere sus tipos de Debilidad a Lanza del Frío Infinito.","tipo":"Talento","elemento":null},{"nombre":"Sin escapatoria","descripcion":"Cuando la Aniquiladora del Mistral Desolador: Madre de Falsedades lanza Torrente destrozaalmas o Acorde del génesis, efectúa un lanzamiento adicional a los objetivos fijados por Lanza del Frío Infinito.","tipo":"Talento","elemento":null},{"nombre":"Resolución tenaz","descripcion":"Reduce el daño que reciben todos los enemigos, pero aumenta el daño recibido por cada tipo de Debilidad poseído.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-4035010', 'honkai-star-rail', 'Anticreador, Odio Desbordante', 'Anti-Creator, Hatred Inundate', 'jefe', 'jefe', 'Criatura de la marea oscura', 'El núcleo del antiguo cetro, el odio materializado de Amphoreus. Ha grabado el sufrimiento de cientos de millones de almas, y la sangre de innumerables corderos se ha fusionado en una oscuridad absoluta. La oscuridad infinita e interminable fluye desde un caparazón destrozado, impulsando al gigante sin cabeza.
Este caparazón, forjado por un flujo de odio incesante, parece contener en sus profundidades un corazón envuelto en el fuego del caos.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4035010.webp', '["Hielo","Rayo","Cuántico"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Fuego","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, null, '[{"nombre":"Sangre derramada y heridas","descripcion":"Inflige Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Tejido de sufrimiento y muerte","descripcion":"Inflige Daño Físico a todos los aliados.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"No hay lealtad para los tiranos","descripcion":"Inflige Daño Cuántico al objetivo fijado y reduce su energía.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"La caverna no será el fin","descripcion":"Inflige Daño Imaginario al objetivo fijado y lo afecta con el estado de Bloqueo de acción.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"La corona de divinidad se destrozará","descripcion":"Inflige una gran cantidad de Daño Cuántico a todos los aliados y reduce su energía.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"La prisión del espíritu arderá","descripcion":"Inflige una gran cantidad de Daño Imaginario al objetivo fijado y lo afecta con el estado de Bloqueo de acción.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Resistir y destruir","descripcion":"Entra en el estado Resistir y destruir, regenera todos los PV de Mythos y Logos, no puede ser atacado antes de la siguiente acción y lanza \"Calcinar el cielo y abandonar el mundo\" a todos los aliados en la siguiente acción. El estado de Resistir y destruir se disipa cuando todos los Mythos y Logos son afectados con el estado Herida grave.","tipo":"Habilidad","elemento":null},{"nombre":"Calcinar el cielo y abandonar el mundo","descripcion":"Inflige una gran cantidad de Daño Físico a todos los aliados. Si Mythos no está afectado con Herida grave, un personaje aliado al azar es afectado con Bloqueo de acción. Si Logos no está afectado con Herida grave, la energía de todos los aliados se reduce.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Odio de Amphoreus","descripcion":"Las habilidades de ataque de Anticreador, Mythos o Logos aumentan Odio de Amphoreus. Cuando Odio aumenta, Ferrotumba lanza Caída de la Erudición, lo que reduce los PV máx. y el límite de pts. de habilidad básica que pueden regenerar los aliados. Cuando Odio disminuye, este efecto se debilita. Cuando Odio alcanza su límite máximo, lanza inmediatamente \"Cenizas que entierran la génesis\". Cuantos menos personajes aliados del equipo haya en el campo de batalla, menos aumenta Odio de Amphoreus","tipo":"Talento","elemento":null},{"nombre":"Treinta millones de ciclos de pecado","descripcion":"Cuando Mythos o Logos reciben daño, Anticreador también recibe daño. Anticreador, Mythos y Logos reciben un daño reducido al comienzo. Este efecto de reducción de daño se debilita por cada Mythos y Logos que entren en el estado Herida grave. Cuando ambos entran en el estado Herida grave a la vez, este efecto se disipa.","tipo":"Talento","elemento":null},{"nombre":"Cenizas que entierran la génesis","descripcion":"Si Odio de Amphoreus llega al máximo, perderás el combate.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-4064012', 'honkai-star-rail', 'Árbitro del Abismo de la Perplejidad', 'Arbiter of the Lost Abyss', 'jefe', 'jefe', 'Mnemoduende de Sangre Dorada', 'La locura que aún persistía en los restos de los Mnemoduendes de Sangre Dorada fue extraída y refinada por Larganoche, quien la sintetizó en un monstruo aún más retorcido y extraño.
Siguiendo las instrucciones de su creadora, esta criatura determina qué debe ser recordado y qué olvidado, y devora los recuerdos redundantes e inútiles, silenciándolos con el tiempo.
"Para que brote una nueva vida, su semilla debe estar muerta".', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_4064010.webp', '["Físico","Fuego","Rayo","Imaginario"]'::jsonb, '[{"elemento":"Hielo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, null, '[{"nombre":"Colmillo de sangre viciada","descripcion":"Inflige Daño Imaginario a un aliado. Si el objetivo tiene un escudo, activa Sismo de barrera.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Ejecución preparada","descripcion":"Invoca a Mnemoduende de Sangre Dorada: Faisán. Cada vez que se elimina una invocación, se activa Sismo de barrera.","tipo":"Habilidad","elemento":null},{"nombre":"Mirada de sangre viciada","descripcion":"Fija como objetivo a un personaje aliado y aumenta la VEL de esta unidad. Lanza Colmillo de sangre viciada y Sierra de sangre viciada contra ese objetivo durante varios turnos. Después de lanzar esta habilidad, realiza una acción adicional.","tipo":"Habilidad","elemento":null},{"nombre":"Sierra de sangre viciada","descripcion":"Inflige una gran cantidad de Daño Imaginario a un aliado y convierte en Corrosión una parte de los PV reducidos al objetivo. Si el objetivo tiene un escudo, activa Sismo de barrera.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Tenazas de sangre viciada","descripcion":"Inflige una gran cantidad de Daño Imaginario a todos los aliados y convierte en Corrosión una parte de los PV reducidos a los objetivos.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Señalamiento del culpable","descripcion":"Entra en el estado de Recarga. Lanza Decapitación de sangre viciada en la siguiente acción y selecciona 1 personaje aliado para que reciba el daño máximo de Decapitación de sangre viciada y Corrupción de sangre viciada.","tipo":"Habilidad","elemento":null},{"nombre":"Decapitación de sangre viciada","descripcion":"Inflige Daño Imaginario a los personajes aliados que no han sido seleccionados por Señalamiento del culpable e inflige una gran cantidad de Daño Imaginario al personaje aliado seleccionado por Señalamiento del culpable. Aplica a este último Corrupción de sangre viciada según la cantidad de daño recibido sin absorber por un escudo.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Piel dura","descripcion":"Al comenzar la batalla y al cambiar de fase, esta unidad entra en el estado de Defensa potenciada, lo que aumenta su DEF en gran medida. Tras romperse su Debilidad, se disipa el estado de Defensa potenciada.","tipo":"Habilidad","elemento":null},{"nombre":"Sismo de barrera","descripcion":"Al activar Sismo de barrera, esta unidad obtiene 1 acumulación de DEF reducida.","tipo":"Habilidad","elemento":null},{"nombre":"Fragmentación","descripcion":"Al comenzar la batalla o al cambiar de fase, esta unidad se divide en Mnemoduende de Sangre Dorada: Faisán, Mnemoduende de Sangre Dorada: Perro y Mnemoduende de Sangre Dorada: Serpiente Alada. Esos Mnemoduendes de Sangre Dorada obtienen Unificación y esta unidad obtiene Linaje débil.\nCada vez que un Mnemoduende de Sangre Dorada con Unificación actúa, esta unidad pierde 1 punto de Linaje débil.\nCuando todos los Mnemoduendes de Sangre Dorada con Unificación están afectados con Muerte fingida, vuelven a fusionarse y se convierten en Árbitro del Abismo de la Perplejidad. La Firmeza de Árbitro del Abismo de la Perplejidad se reduce en función de la cantidad de Linaje débil que quede en ese momento.","tipo":"Habilidad","elemento":null},{"nombre":"Cuerpo degradado","descripcion":"Esta unidad y sus invocaciones obtienen Cuerpo degradado. Cuando un aliado lanza un ataque contra un enemigo con Cuerpo degradado y aplica un estado negativo, reduce levemente la Firmeza de dicha unidad enemiga y le inflige Daño verdadero.","tipo":"Habilidad","elemento":null}]'::jsonb),
  ('hsr-enemy-3024010', 'honkai-star-rail', 'Argenti', 'Argenti', 'jefe', 'jefe', 'Cosmos', 'Un clásico caballero de los Caballeros de la Belleza que busca piadosamente a su Eón desaparecido, Idrila, la Belleza.
Es franco y cándido y vaga por el cosmos propugnando las virtudes del buen nombre de Idrila.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3024010.webp', '["Físico","Fuego","Hielo"]'::jsonb, '[{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Físico","Fuego","Hielo"],"resistencias":[{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Hielo","Cuántico"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Fuego","Hielo","Rayo"],"resistencias":[{"elemento":"Físico","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Hielo","Viento"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Fuego","Imaginario"],"resistencias":[{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20}]},{"debilidades":["Físico","Hielo","Cuántico"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Devoción","descripcion":"Inflige Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Devoción imbuida","descripcion":"Inflige Daño Físico a un aliado determinado y a los aliados adyacentes.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Encrucijada","descripcion":"Invoca aleatoriamente estatuas de Punta de Lanza, El Escudo y La Distinguida.","tipo":"Habilidad","elemento":null},{"nombre":"Alma de perseverancia","descripcion":"Lanza un Alma de la Belleza desde una de las estatuas y mejora la habilidad de la estatua que lanza el alma.","tipo":"Habilidad","elemento":null},{"nombre":"Himno del coraje espléndido","descripcion":"Inflige Daño Físico a todos los aliados.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Así habló el espíritu del amor","descripcion":"Lanza Alma de la Belleza desde una de las estatuas. Mejora la habilidad de la estatua con Alma libre y hace que actúe inmediatamente.","tipo":"Habilidad","elemento":null},{"nombre":"Pecado y absolución","descripcion":"Lanza Alma de la Belleza desde todas las estatuas y mejora la habilidad de la estatua con Alma libre.","tipo":"Habilidad","elemento":null},{"nombre":"Caballeros","descripcion":"Invoca 4 Puntas de Lanza. Si hay estatuas en el campo de batalla, regenera todos sus PV.","tipo":"Habilidad","elemento":null},{"nombre":"Martirio de la grandiosidad","descripcion":"Tras cada uso de Himno del coraje espléndido, aumenta el daño que inflige. Este efecto se puede acumular.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-3024011', 'honkai-star-rail', 'Argenti (intacto)', 'Argenti (Complete)', 'jefe', 'jefe', null, 'Una proyección intacta creada por un código alterado. La referencia original es un clásico caballero de los Caballeros de la Belleza.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_3024010.webp', '["Físico","Fuego","Hielo"]'::jsonb, '[{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]'::jsonb, '[{"debilidades":["Físico","Fuego","Hielo"],"resistencias":[{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Cuántico","valor":20},{"elemento":"Imaginario","valor":20}]},{"debilidades":["Físico","Hielo","Cuántico"],"resistencias":[{"elemento":"Fuego","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Viento","valor":20},{"elemento":"Imaginario","valor":20}]}]'::jsonb, '[{"nombre":"Devoción","descripcion":"Inflige Daño Físico a un aliado.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Devoción imbuida","descripcion":"Inflige Daño Físico a un aliado y a los aliados adyacentes.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Encrucijada","descripcion":"Invoca aleatoriamente estatuas de Punta de Lanza, El Escudo y La Distinguida.","tipo":"Habilidad","elemento":null},{"nombre":"Así habló el espíritu del amor","descripcion":"Lanza Alma de la Belleza desde una de las estatuas. Mejora la habilidad de la estatua con Alma libre y hace que actúe inmediatamente.","tipo":"Habilidad","elemento":null},{"nombre":"Himno del coraje espléndido","descripcion":"Inflige Daño Físico a todos los aliados.","tipo":"Habilidad","elemento":"Físico"},{"nombre":"Pecado y absolución","descripcion":"Lanza Alma de la Belleza desde todas las estatuas y mejora la habilidad de la estatua con Alma libre.","tipo":"Habilidad","elemento":null},{"nombre":"Caballeros","descripcion":"Invoca 4 Puntas de Lanza. Si hay estatuas en el campo de batalla, regenera todos sus PV.","tipo":"Habilidad","elemento":null},{"nombre":"Martirio de la grandiosidad","descripcion":"Tras cada uso de Himno del coraje espléndido, aumenta el daño que inflige. Este efecto se puede acumular.","tipo":"Talento","elemento":null}]'::jsonb),
  ('hsr-enemy-8015030', 'honkai-star-rail', 'Asat Pramad, Señor de Saṃvartasthāyi', 'Lord of Saṃvartasthāyi, Asat Pramad', 'jefe', 'jefe', 'Legión Antimateria', 'Los tres rostros de Paranirmitavaśavartin, y la verdadera apariencia del Devastador que domina las posibilidades.
Todas las cosas y fenómenos atraviesan la Formación, la Subsistencia y la Decadencia para, finalmente, convertirse en Vacío. La Exultación y el tiempo son enemigos mortales. Bajo el inevitable desgaste de los años, todo acabará regresando a la nada absoluta.
Lleva a cabo el mandato celestial de la Destrucción y la gran obra de extinguir las mentes de todos los seres sintientes del mundo.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8015030.webp', '["Fuego","Viento","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, null, '[{"nombre":"Farsa de la existencia","descripcion":"Inflige daño a todos los aliados.","tipo":"Habilidad","elemento":null},{"nombre":"Mirada burlona","descripcion":"Inflige daño a un aliado.","tipo":"Habilidad","elemento":null},{"nombre":"Deleite de la Nihilidad","descripcion":"Inflige daño a todos los aliados.","tipo":"Habilidad","elemento":null},{"nombre":"Triple desprecio","descripcion":"Inflige daño a todos los aliados.","tipo":"Habilidad","elemento":null},{"nombre":"Siembra de memes","descripcion":"Entra en estado de Recarga. Aplica un total de 4 acumulaciones de Meme explosivo a los personajes aliados.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Fiesta de memes explosivos","descripcion":"Detona todos los Memes explosivos.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Partida que marca el destino","descripcion":"Lanza varios dados y elige uno para que surta efecto en el equipo aliado. Los demás surten efecto en el equipo enemigo.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Fuera todas las bolas","descripcion":"Inflige Daño Imaginario a todos los aliados y tiene una gran probabilidad de afectar con Reverberación potente a un aliado al azar.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Que este viaje te lleve a la Destrucción","descripcion":"Inflige una gran cantidad de Daño Cuántico a todos los aliados.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Que la Exultación sea eternamente silenciada","descripcion":"Inflige una gran cantidad de Daño Cuántico a todos los aliados.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Encarnación de tres facetas","descripcion":"En este combate, Asat Pramad, Señor de Saṃvartasthāyi, posee las tres facetas Formación, Subsistencia y Decadencia. Cada una tiene sus propias habilidades únicas.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Chistes del mismísimo infierno","descripcion":"Añade Empieza el juego al orden de acción. Cada vez que Empieza el juego actúa, disipa los estados negativos de Control y el estado de Ruptura de Debilidad de Asat Pramad, Señor de Saṃvartasthāyi, y lanza Que este viaje te lleve a la Destrucción.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Tres facetas en una","descripcion":"Durante esta fase, Formación, Subsistencia y Decadencia comparten PV, y las facetas de Formación y Subsistencia no se pueden seleccionar. Cada vez que Empieza el juego actúa, se disipan los estados negativos de Control y el estado de Ruptura de Debilidad de Asat Pramad, Señor de Saṃvartasthāyi, y lanza Que la Exultación sea eternamente silenciada.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Telonero","descripcion":"Añade Entrada triunfal al orden de acción. Cada vez que Entrada triunfal actúa, invoca a Académico de la Comedia.","tipo":"Habilidad","elemento":"Cuántico"}]'::jsonb),
  ('hsr-enemy-8015050', 'honkai-star-rail', 'Asat Pramad, Señor de Saṃvartasthāyi (Decadencia)', 'Lord of Saṃvartasthāyi, Asat Pramad: "Decay"', 'jefe', 'jefe', 'Legión Antimateria', 'El Devastador llamado Asat Pramad está diseñando un juego para destruir la Exultación.
Invade planetas incapaces de resistir y utiliza la sangre dorada para crear linajes nacidos para la destrucción, con el único fin de burlarse de la vida y mofarse de la Exultación.
Sin embargo, esto está lejos de satisfacerlo. Para lograr su gran plan de eliminar a la Exultación, está decidido a despertar al Eón y completar así la destrucción más absoluta, aunque tal vez el precio a pagar sea él mismo.
Finalmente, con la llegada del Expreso una vez más, ha llegado el momento oportuno. Entra en el juego con una identidad robada para intentar crear el desenlace más magnífico y absoluto.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8015050.webp', '["Fuego","Viento","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, null, '[{"nombre":"Farsa de la existencia","descripcion":"Inflige daño a todos los aliados.","tipo":"Habilidad","elemento":null},{"nombre":"Mirada burlona","descripcion":"Inflige daño a un aliado.","tipo":"Habilidad","elemento":null},{"nombre":"Fuera todas las bolas","descripcion":"Inflige Daño Imaginario a todos los aliados y tiene una gran probabilidad de afectar con Reverberación potente a un aliado al azar.","tipo":"Habilidad","elemento":"Imaginario"},{"nombre":"Que la Exultación sea eternamente silenciada","descripcion":"Inflige una gran cantidad de Daño Cuántico a todos los aliados.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Deleite de la Nihilidad","descripcion":"Inflige daño a todos los aliados.","tipo":"Habilidad","elemento":null},{"nombre":"Triple desprecio","descripcion":"Inflige daño a todos los aliados.","tipo":"Habilidad","elemento":null},{"nombre":"Encarnación de tres facetas","descripcion":"En este combate, Asat Pramad, Señor de Saṃvartasthāyi, posee las tres facetas Formación, Subsistencia y Decadencia. Cada una tiene sus propias habilidades únicas.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Chistes del mismísimo infierno","descripcion":"Añade Empieza el juego al orden de acción. Cada vez que Empieza el juego actúa, disipa los estados negativos de Control y el estado de Ruptura de Debilidad de Asat Pramad, Señor de Saṃvartasthāyi, y lanza Que este viaje te lleve a la Destrucción.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Tres facetas en una","descripcion":"Durante esta fase, Formación, Subsistencia y Decadencia comparten PV, y las facetas de Formación y Subsistencia no se pueden seleccionar. Cada vez que Empieza el juego actúa, se disipan los estados negativos de Control y el estado de Ruptura de Debilidad de Asat Pramad, Señor de Saṃvartasthāyi, y lanza Que la Exultación sea eternamente silenciada.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Telonero","descripcion":"Añade Entrada triunfal al orden de acción. Cada vez que Entrada triunfal actúa, invoca a Académico de la Comedia.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Siembra de memes","descripcion":"Entra en estado de Recarga. Aplica un total de 4 acumulaciones de Meme explosivo a los personajes aliados.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Fiesta de memes explosivos","descripcion":"Detona todos los Memes explosivos.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Partida que marca el destino","descripcion":"Lanza varios dados y elige uno para que surta efecto en el equipo aliado. Los demás surten efecto en el equipo enemigo.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Que este viaje te lleve a la Destrucción","descripcion":"Inflige una gran cantidad de Daño Cuántico a todos los aliados.","tipo":"Habilidad","elemento":"Cuántico"}]'::jsonb),
  ('hsr-enemy-8015040', 'honkai-star-rail', 'Asat Pramad, Señor de Saṃvartasthāyi (Subsistencia)', 'Lord of Saṃvartasthāyi, Asat Pramad: "Existence"', 'jefe', 'jefe', 'Legión Antimateria', 'El piloto llamado Yoveo se embarcó en una expedición trazacaminos para salvar a la Exultación.
Ayudó a los planetas a superar sus crisis y resolvió los problemas del universo con el único propósito de encontrar un antídoto para la Exultación.
Sin embargo, a medida que su viaje se prolongaba, fue testigo de cómo cada vez más mundos conocidos se sumían en la decadencia y la ruina. Incluso hubo un mundo que intentó pagar la salvación brindada por la tripulación del Expreso Astral con la destrucción mutua.
Finalmente, tras la caída del Eón Trazacaminos y después de haber presenciado con sus propios ojos el final de Adlivun, por fin comprendió cuál era el único antídoto para la Exultación: la Destrucción.', 'https://static.nanoka.cc/assets/hsr/monsterfigure/Monster_8015040.webp', '["Fuego","Viento","Imaginario"]'::jsonb, '[{"elemento":"Físico","valor":20},{"elemento":"Hielo","valor":20},{"elemento":"Rayo","valor":20},{"elemento":"Cuántico","valor":20}]'::jsonb, null, '[{"nombre":"Farsa de la existencia","descripcion":"Inflige daño a todos los aliados.","tipo":"Habilidad","elemento":null},{"nombre":"Mirada burlona","descripcion":"Inflige daño a un aliado.","tipo":"Habilidad","elemento":null},{"nombre":"Partida que marca el destino","descripcion":"Lanza varios dados y elige uno para que surta efecto en el equipo aliado. Los demás surten efecto en el equipo enemigo.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Encarnación de tres facetas","descripcion":"En este combate, Asat Pramad, Señor de Saṃvartasthāyi, posee las tres facetas Formación, Subsistencia y Decadencia. Cada una tiene sus propias habilidades únicas.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Chistes del mismísimo infierno","descripcion":"Añade Empieza el juego al orden de acción. Cada vez que Empieza el juego actúa, disipa los estados negativos de Control y el estado de Ruptura de Debilidad de Asat Pramad, Señor de Saṃvartasthāyi, y lanza Que este viaje te lleve a la Destrucción.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Tres facetas en una","descripcion":"Durante esta fase, Formación, Subsistencia y Decadencia comparten PV, y las facetas de Formación y Subsistencia no se pueden seleccionar. Cada vez que Empieza el juego actúa, se disipan los estados negativos de Control y el estado de Ruptura de Debilidad de Asat Pramad, Señor de Saṃvartasthāyi, y lanza Que la Exultación sea eternamente silenciada.","tipo":"Habilidad","elemento":"Cuántico"},{"nombre":"Telonero","descripcion":